273	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
274	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
275	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
276	// collide even under aggressive PID reuse (B13). The tmp lives in the
277	// same directory as `path` so the rename is intra-filesystem.
278	static int write_blob_atomic(const void *data, size_t len, const char *path)
279	{
280	    char tmp[PATH_MAX];
281	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
282	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
283	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
284	        return -1;
285	    }
286	    int fd = g_mkstemp(tmp);
287	    if (fd < 0) {
288	        perror("hybrid_handoff: g_mkstemp");
289	        return -1;
290	    }
291	    // g_mkstemp creates the file 0600; no further chmod needed.
292	    ssize_t got = write(fd, data, len);
293	    if (got != (ssize_t) len) {
294	        perror("hybrid_handoff: write");
295	        close(fd);
296	        unlink(tmp);
297	        return -1;
298	    }
299	    fsync(fd);
300	    close(fd);
301	    if (rename(tmp, path) != 0) {
302	        perror("hybrid_handoff: rename");
303	        unlink(tmp);
304	        return -1;
305	    }
306	    return 0;
307	}
